INSERT INTO products (id, farmer_id, category_id, name, description, price, stock_quantity, unit, image_url, status) VALUES
(2, 4, 1, 'Diamond Red Potatoes (Bogra)', 'Direct harvest from Bogra fields. Grade-A diamond potatoes with smooth skin, rich starch content and high storage shelf-life.', 35, 450, 'kg', 'https://images.unsplash.com/photo-1518977676601-b53f82aba655?auto=format&fit=crop&w=700&q=80', 'active'),
(3, 5, 1, 'Fresh Farm Vine Tomatoes', 'Sun-ripened, firm red tomatoes naturally cultivated without carbide or chemical accelerators. Juicy and full of lycopene.', 48, 220, 'kg', 'https://images.unsplash.com/photo-1546094096-0df4bcaaa337?auto=format&fit=crop&w=700&q=80', 'active'),
(4, 6, 1, 'Organic Green Spinach (Palong Shak)', 'Tender dark green spinach harvested at dawn. Chemical pesticide-free, packed with iron and vital minerals.', 30, 120, 'kg', 'https://images.unsplash.com/photo-1576045057995-568f588f82fb?auto=format&fit=crop&w=700&q=80', 'active'),
(5, 7, 1, 'Purple Round Eggplant (Tal Begun)', 'Traditional round eggplant from Jessore region. Glossy purple skin and soft fleshy interior ideal for roasting and frying.', 55, 180, 'kg', 'https://images.unsplash.com/photo-1528825871115-3581a5387919?auto=format&fit=crop&w=700&q=80', 'active'),
(6, 8, 1, 'Fresh Piquant Green Chilies', 'Fiery, aromatic green chilies freshly hand-plucked from Manikganj riverbanks. Crisp texture and intense spice profile.', 90, 140, 'kg', 'https://images.unsplash.com/photo-1563565375-f3fdfdbefa83?auto=format&fit=crop&w=700&q=80', 'active'),
(7, 4, 1, 'Crisp Green Bitter Gourd (Korola)', 'Farm-fresh bitter gourd full of dietary nutrients, natural insulin regulators, and digestive benefits.', 65, 130, 'kg', 'https://images.unsplash.com/photo-1604977042946-1eecc30f269e?auto=format&fit=crop&w=700&q=80', 'active'),
(8, 5, 1, 'Fresh Pointed Gourd (Deshi Potol)', 'Hand-picked small tender pointed gourd with thin skin and minimal seeds. Delivered crisp within 24 hours of harvest.', 50, 200, 'kg', 'https://images.unsplash.com/photo-1593105544559-ecb03bf76f82?auto=format&fit=crop&w=700&q=80', 'active'),
(9, 6, 1, 'White Cauliflower (Fulkopi)', 'Dense, pure white cauliflower heads protected naturally under green foliage. Pesticide residue-free produce.', 40, 160, 'piece', 'https://images.unsplash.com/photo-1568584711075-3d021a7c3ca3?auto=format&fit=crop&w=700&q=80', 'active'),
(10, 7, 1, 'Fresh Green Cabbage (Badhakopi)', 'Crisp, layered fresh green cabbage heads cultivated in alluvial soil. Ideal for crunchy salads and curry.', 35, 190, 'piece', 'https://images.unsplash.com/photo-1611105637889-3ebe7d8794c4?auto=format&fit=crop&w=700&q=80', 'active'),
(11, 8, 1, 'Fresh Red Amaranth (Lal Shak)', 'Nutrient-rich village Lal Shak with vibrant natural crimson leaves. High in anthocyanin and vitamin A.', 25, 110, 'kg', 'https://images.unsplash.com/photo-1576045057995-568f588f82fb?auto=format&fit=crop&w=700&q=80', 'active'),
(12, 4, 1, 'Crisp Sweet Carrots (Gajor)', 'Sweet, firm organic orange carrots freshly washed and graded. Great for juicing, cooking, and raw salads.', 60, 175, 'kg', 'https://images.unsplash.com/photo-1598170845058-32b9d6a5da37?auto=format&fit=crop&w=700&q=80', 'active'),
(13, 5, 1, 'Sweet Bottle Gourd (Kochi Lau)', 'Tender, water-rich bottle gourd directly from village trestles. Naturally sweet and refreshing.', 55, 140, 'piece', 'https://images.unsplash.com/photo-1506917728037-b9bf01ac4776?auto=format&fit=crop&w=700&q=80', 'active'),
(14, 6, 2, 'Rajshahi Fazli Mango (Premium)', 'Legendary Rajshahi Fazli mangoes tree-ripened with natural fragrance, fibrous-free sweet pulp, and large golden size.', 180, 300, 'kg', 'https://images.unsplash.com/photo-1553279768-865429fa0078?auto=format&fit=crop&w=700&q=80', 'active'),
(15, 7, 2, 'Sweet Amrapali Mango (Chapainawabganj)', 'Rich aromatic Amrapali mangoes from northern orchards. Renowned for deep orange interior and high sweetness brix.', 160, 280, 'kg', 'https://images.unsplash.com/photo-1553279768-865429fa0078?auto=format&fit=crop&w=700&q=80', 'active'),
(16, 8, 2, 'Kazi Sweet Guava (Peyara)', 'Crisp green Barisal floating market guavas with thick flesh, mild sweet taste, and high vitamin C percentage.', 70, 250, 'kg', 'https://images.unsplash.com/photo-1536511135898-10e3097cb006?auto=format&fit=crop&w=700&q=80', 'active'),
(17, 4, 2, 'Sagor Sweet Banana (Narsingdi)', 'Naturally ripened Sagor bananas from Narsingdi agro belts without chemical smoke or artificial carbide.', 90, 220, 'dozen', 'https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?auto=format&fit=crop&w=700&q=80', 'active'),
(18, 5, 2, 'Rangpur Honey Queen Pineapple', 'Juicy, fragrant wild honey-queen pineapples grown in the red soil of Modhupur/Rangpur.', 65, 180, 'piece', 'https://images.unsplash.com/photo-1550258987-190a2d41a8ba?auto=format&fit=crop&w=700&q=80', 'active'),
(19, 6, 2, 'Fresh Green Raw Papaya (Kacha Pepe)', 'High-enzyme green papayas, ideal for digestion, meat tenderizing, and everyday healthy light curries.', 35, 210, 'kg', 'https://images.unsplash.com/photo-1517282009859-f000ec3b26fe?auto=format&fit=crop&w=700&q=80', 'active'),
(20, 7, 2, 'Organic Red Watermelon (Bangla Tormuj)', 'Sweet, deep crimson watermelons harvested from Bhola and coastal chars. Naturally sweet and refreshing.', 45, 350, 'kg', 'https://images.unsplash.com/photo-1587049352846-4a222e784d38?auto=format&fit=crop&w=700&q=80', 'active'),
(21, 8, 2, 'Sundarban Coastal Dragon Fruit', 'Exotic red-flesh dragon fruit locally grown in organic orchards. High in antioxidants, fiber, and iron.', 240, 95, 'kg', 'https://images.unsplash.com/photo-1527325678964-54921661f888?auto=format&fit=crop&w=700&q=80', 'active'),
(22, 4, 2, 'Sweet Green Malta (Deshi Agro)', 'Juicy BARI Malta-1 with sweet green rind and overflowing citrus juice, free from synthetic preservatives.', 130, 160, 'kg', 'https://images.unsplash.com/photo-1590502593747-42a996133562?auto=format&fit=crop&w=700&q=80', 'active'),
(23, 5, 2, 'Fresh Farm Strawberries (Rajshahi)', 'Vibrant red organic strawberries grown in winter polytunnels. Deliciously sweet-tart with intense berry scent.', 380, 60, 'kg', 'https://images.unsplash.com/photo-1464965911861-746a04b4bca6?auto=format&fit=crop&w=700&q=80', 'active'),
(24, 6, 3, 'Dinajpur Aromatic Miniket Rice (Auto Mill)', 'Long slender grain Miniket rice from Dinajpur. Triple sortex-cleaned, no plastic polish, cooks fluffy and fragrant.', 74, 800, 'kg', 'https://images.unsplash.com/photo-1586201375761-83865001e31c?auto=format&fit=crop&w=700&q=80', 'active'),
(25, 7, 3, 'Bogra Traditional Nazirshail Rice', 'Non-sticky, firm grain Nazirshail rice with authentic earthy grain aroma and superior digestibility.', 78, 650, 'kg', 'https://images.unsplash.com/photo-1586201375761-83865001e31c?auto=format&fit=crop&w=700&q=80', 'active'),
(26, 8, 3, 'Chinigura Polao Aromatic Rice', 'Small grain fragrant Chinigura rice. Traditional heritage harvest perfect for celebratory Polao, Biryani, and Payesh.', 140, 450, 'kg', 'https://images.unsplash.com/photo-1536304993881-ff6e9eefa2a6?auto=format&fit=crop&w=700&q=80', 'active'),
(27, 4, 3, 'Organic Unpolished Brown Rice', '100% whole grain brown rice retaining bran layer and germ. Ideal for low glycemic diets and cardiovascular wellness.', 95, 320, 'kg', 'https://images.unsplash.com/photo-1595855759920-86582396756a?auto=format&fit=crop&w=700&q=80', 'active'),
(28, 5, 3, 'Whole Grain Farm Wheat (Deshi Gom)', 'Freshly harvested golden wheat grains dried under open village sunshine. High in dietary bran and vegetable protein.', 52, 500, 'kg', 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?auto=format&fit=crop&w=700&q=80', 'active'),
(29, 6, 3, 'Organic Red Lentils (Deshi Masoor Dal)', 'Small grain country Masoor Dal with quick cooking properties and deep rich flavor. Free from added artificial coloring.', 135, 400, 'kg', 'https://images.unsplash.com/photo-1585996746979-4a413d08e0eb?auto=format&fit=crop&w=700&q=80', 'active'),
(30, 7, 3, 'Polished Yellow Moong Dal (Bhaja)', 'Lightly roasted golden Moong Dal delivering exquisite nutty fragrance. Rich in easily digestible protein.', 155, 310, 'kg', 'https://images.unsplash.com/photo-1612773229774-7d52674208a0?auto=format&fit=crop&w=700&q=80', 'active'),
(31, 8, 3, 'Deshi Chickpeas (Chola Boot)', 'Small brown deshi chickpeas packed with plant-based protein, iron, and fiber for daily wholesome nutrition.', 110, 380, 'kg', 'https://images.unsplash.com/photo-1515543237350-b3eea1ec8082?auto=format&fit=crop&w=700&q=80', 'active'),
(32, 4, 4, 'Pure Raw Cow Milk (Pabna Pastures)', '100% unadulterated raw grass-fed cow milk sourced from dairy clusters along the Padma basin. Chilled immediately.', 85, 200, 'liter', 'https://images.unsplash.com/photo-1550583724-b2692b85b150?auto=format&fit=crop&w=700&q=80', 'active'),
(33, 5, 4, 'Traditional Cultured Deshi Cow Ghee', 'Handmade Bilona churned ghee prepared from cultured curd cream. Golden granules and mesmerizing heritage aroma.', 1450, 80, 'kg', 'https://images.unsplash.com/photo-1631451095765-2c91616fc9e6?auto=format&fit=crop&w=700&q=80', 'active'),
(34, 6, 4, 'Fresh Village Cottage Cheese (Paneer)', 'Soft, melt-in-mouth fresh artisan paneer prepared daily with pure cow milk and natural lemon whey.', 520, 90, 'kg', 'https://images.unsplash.com/photo-1628088062854-d1870b4553da?auto=format&fit=crop&w=700&q=80', 'active'),
(35, 7, 4, 'Traditional Bogra Sweet Curd (Mishti Doi)', 'Authentic clay-pot baked sweet yogurt from Bogra masters. Thick caramelized crust and luscious texture.', 280, 120, 'pot', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=700&q=80', 'active'),
(36, 8, 4, 'Farm Fresh Cultured Butter (Makhon)', 'Unsalted pure country butter churned directly from fresh cream. Zero artificial preservatives or emulsifiers.', 780, 75, 'kg', 'https://images.unsplash.com/photo-1589985270826-4b7bb135bc9d?auto=format&fit=crop&w=700&q=80', 'active'),
(37, 4, 4, 'Natural Deshi Buttermilk (Matha / Ghol)', 'Cooling, digestive probiotic drink lightly infused with roasted cumin and Himalayan black salt.', 90, 110, 'liter', 'https://images.unsplash.com/photo-1550583724-b2692b85b150?auto=format&fit=crop&w=700&q=80', 'active'),
(38, 5, 4, 'Solid Condensed Milk Khoya (Mawa)', 'Slow-simmered whole milk solid khoya, the essential foundation for traditional Bengali sweets and desserts.', 650, 55, 'kg', 'https://images.unsplash.com/photo-1628088062854-d1870b4553da?auto=format&fit=crop&w=700&q=80', 'active'),
(39, 6, 5, 'High-Yield Boro Paddy Seeds (BRRI-28)', 'Certified high germination rate (92%+) paddy seed stock. Disease tolerant with high grain return per decimal.', 180, 250, 'bag', 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?auto=format&fit=crop&w=700&q=80', 'active'),
(40, 7, 5, 'Hybrid Winter Tomato Seeds (50g)', 'F1 Hybrid disease-resistant tomato seeds producing uniform bright red firm fruits with high harvest potential.', 320, 140, 'packet', 'https://images.unsplash.com/photo-1530595467537-0b5996c41f2d?auto=format&fit=crop&w=700&q=80', 'active'),
(41, 8, 5, 'Organic Red Amaranth Lal Shak Seeds', 'Fast sprouting leafy green seeds. Germinates within 4-5 days; perfect for rooftop gardens and field farming.', 95, 300, 'packet', 'https://images.unsplash.com/photo-1608797178974-15b35a61ded8?auto=format&fit=crop&w=700&q=80', 'active'),
(42, 4, 5, 'High-Yielding Eggplant Seeds (Begun)', 'Pest-tolerant eggplant seeds selected from hardy regional varieties. Produces tender glossy fruits over 6 months.', 120, 180, 'packet', 'https://images.unsplash.com/photo-1530595467537-0b5996c41f2d?auto=format&fit=crop&w=700&q=80', 'active'),
(43, 5, 5, 'Bari Shorshe-14 High Oil Mustard Seeds', 'High oil yield mustard seeds. Short duration crop fitting comfortably between Aman and Boro rice harvests.', 160, 210, 'bag', 'https://images.unsplash.com/photo-1608797178974-15b35a61ded8?auto=format&fit=crop&w=700&q=80', 'active'),
(44, 6, 5, 'Hybrid Pointed Gourd Potol Root Saplings', 'Healthy root cuttings with high vigor ready for spring planting. Yields continuous harvest through autumn.', 250, 130, 'bundle', 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?auto=format&fit=crop&w=700&q=80', 'active'),
(45, 7, 6, '100% Organic Earthworm Vermicompost (25kg)', 'Nutrient-rich black vermicompost fertilizer packed with beneficial soil microbes, nitrogen, phosphorus, and moisture retainers.', 450, 350, 'bag', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=700&q=80', 'active'),
(46, 8, 6, 'Decomposed Aged Cow Dung Bio-Fertilizer (40kg)', 'Fully composted odorless organic manure. Restores depleted carbon levels and enhances biological activity of soil.', 320, 400, 'bag', 'https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=700&q=80', 'active'),
(47, 4, 6, 'Steamed Bone Meal Natural Phosphate (10kg)', 'Slow-release natural phosphorus and calcium supplement to promote vigorous root branching and abundant flower blossoms.', 580, 190, 'bag', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=700&q=80', 'active'),
(48, 5, 6, 'Mustard Oil Cake Organic Fertilizer (Shorshe Khail 10kg)', 'Traditional high-nitrogen plant booster. Repels root worms and nematodes while nourishing foliage growth.', 490, 280, 'bag', 'https://images.unsplash.com/photo-1608797178974-15b35a61ded8?auto=format&fit=crop&w=700&q=80', 'active'),
(49, 6, 6, 'Trichoderma Bio-Fungicide & Compost Enricher', 'Beneficial antagonistic fungi that protects crop root zones against damping-off, wilt, and root rot diseases.', 290, 150, 'kg', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=700&q=80', 'active'),
(50, 7, 7, 'Traditional Forged Iron Farm Hoe (Deshi Kodal)', 'Heavy duty forged carbon steel hoe with reinforced wooden handle. Balanced weight for digging, tilling, and bed making.', 380, 110, 'piece', 'https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=700&q=80', 'active'),
(51, 8, 7, 'Sharp Serrated Harvest Sickle (Dhan Kaste)', 'Precision micro-serrated sickle blade engineered specifically for swift paddy and grass harvesting with zero arm strain.', 180, 190, 'piece', 'https://images.unsplash.com/photo-1592417817098-8f3d69104a47?auto=format&fit=crop&w=700&q=80', 'active'),
(52, 4, 7, 'Heavy Duty 16L Agriculture Knapsack Sprayer', 'Durable polyethylene sprayer tank with brass spray lance, ergonomic backpack straps, and dual-head fine mist nozzles.', 1350, 85, 'piece', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=700&q=80', 'active'),
(53, 5, 7, 'High Carbon Orchard Pruner & Branch Cutter', 'Japanese style bypass pruning shears with razor-sharp carbon steel blades for clean cuts without damaging bark.', 420, 130, 'piece', 'https://images.unsplash.com/photo-1592417817098-8f3d69104a47?auto=format&fit=crop&w=700&q=80', 'active'),
(54, 6, 7, 'Traditional Hand Weeder (Niri / Khurpi)', 'Indispensable hand weeding tool for precise soil aeration, weed removal around delicate vegetable roots.', 120, 220, 'piece', 'https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=700&q=80', 'active'),
(55, 7, 7, 'Drip Irrigation Starter Kit (50 Meter System)', 'Complete micro-drip irrigation kit with UV-resistant tubing, 50 adjustable drippers, tee connectors, and tap adapter.', 1850, 60, 'set', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=700&q=80', 'active')
