-- AgroTrade Seed Data
-- Seed file containing Categories, Test Users (test1-test11), and 50+ Agricultural Products
USE agrotrade_db;

-- 1. CATEGORIES
ON DUPLICATE KEY UPDATE name=VALUES(name), slug=VALUES(slug);

-- 2. USERS (Password for all accounts is: password)
ON DUPLICATE KEY UPDATE full_name=VALUES(full_name), password_hash=VALUES(password_hash), role=VALUES(role), is_active=VALUES(is_active);

-- 3. AGRICULTURAL PRODUCTS (50+ items)
ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), stock_quantity=VALUES(stock_quantity), status=VALUES(status);
